set search_path = '';
select jsonb_build_object(
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'inherit',rolinherit,'createRole',rolcreaterole,'createDb',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypassRls',rolbypassrls,'limit',rolconnlimit,'validUntil',rolvaliduntil,'config',rolconfig) order by rolname) from pg_roles),
 'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) order by nspname) from pg_namespace where nspname in ('auth','storage','extensions')),
 'relations',(select jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'options',c.reloptions) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','storage') and c.relkind in ('r','p','S','v','m')),
 'columns',(select jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl,'generated',a.attgenerated,'identity',a.attidentity) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('auth','storage') and c.relkind in ('r','p','S','v','m') and a.attnum>0 and not a.attisdropped),
 'routines',(select jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'config',p.proconfig) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('auth','storage') and p.prokind='f'),
 'constraints',(select jsonb_agg(jsonb_build_object('relation',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid,false),'validated',convalidated) order by conrelid::regclass::text,conname) from pg_constraint where connamespace in (select oid from pg_namespace where nspname in ('auth','storage'))),
 'indexes',(select jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'definition',pg_get_indexdef(c.oid)) order by n.nspname,c.relname) from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','storage')),
 'triggers',(select jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',t.tgname,'definition',pg_get_triggerdef(t.oid,false),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc f on f.oid=t.tgfoid join pg_namespace fn on fn.oid=f.pronamespace where n.nspname in ('auth','storage') and fn.nspname not in ('public','private') and not t.tgisinternal),
 'policies',(select jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',p.polname,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid),'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when roleid=0 then 'public' else pg_get_userbyid(roleid) end order by roleid) from unnest(p.polroles) roleid)) order by n.nspname,c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','storage') and not coalesce(current_setting('mam.uat.bootstrap_policy_keys',true),'[]')::jsonb ? (n.nspname||'.'||c.relname||':'||p.polname)),
 'defaultACL',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl) order by pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('auth','storage','extensions')),
 'extensions',(select jsonb_agg(jsonb_build_object('name',extname,'version',extversion,'schema',n.nspname,'owner',pg_get_userbyid(extowner)) order by extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace)
);
